create table if not exists public.official_infrastructure_metrics (
 id uuid primary key default gen_random_uuid(),
 snapshot_month date not null,
 dimension text not null check (dimension in ('sector','ministry','progress','onboarding')),
 group_name text not null,
 progress_range text,
 project_count integer check (project_count is null or project_count >= 0),
 cost_lakh_crore numeric(12,2) check (cost_lakh_crore is null or cost_lakh_crore >= 0),
 expenditure_lakh_crore numeric(12,2) check (expenditure_lakh_crore is null or expenditure_lakh_crore >= 0),
 physical_project_count integer check (physical_project_count is null or physical_project_count >= 0),
 financial_project_count integer check (financial_project_count is null or financial_project_count >= 0),
 source_report_url text not null,
 source_note text,
 created_at timestamptz not null default now(),
 unique(snapshot_month,dimension,group_name,progress_range)
);
create index if not exists official_infrastructure_metrics_lookup_idx on public.official_infrastructure_metrics(snapshot_month,dimension,group_name);
alter table public.official_infrastructure_metrics enable row level security;
grant select on public.official_infrastructure_metrics to authenticated;
drop policy if exists "Authenticated users can read official infrastructure metrics" on public.official_infrastructure_metrics;
create policy "Authenticated users can read official infrastructure metrics" on public.official_infrastructure_metrics for select to authenticated using (true);
on conflict (snapshot_month,dimension,group_name,progress_range) do update set
 project_count=excluded.project_count,cost_lakh_crore=excluded.cost_lakh_crore,
 expenditure_lakh_crore=excluded.expenditure_lakh_crore,physical_project_count=excluded.physical_project_count,
 financial_project_count=excluded.financial_project_count,source_report_url=excluded.source_report_url,source_note=excluded.source_note;
